void fill(int arr[], int n) {          /* identical to int *arr */
    printf("%zu\n", sizeof(arr));      /* 4 or 8: pointer size, NOT 20 */
    for (int i = 0; i < n; i++)
        arr[i] = i * i;                /* modifies the caller's array */
}
