class Box {
    int len;
public:
    Box() : len(0) { cout << "default "; }            // default constructor
    Box(int l) : len(l) { cout << "param "; }         // parameterised
    Box(const Box &b) : len(b.len) { cout << "copy "; } // copy constructor
    ~Box() { cout << "destroy" << len << " "; }       // destructor
};
int main() {
    Box a;          // default
    Box b(5);       // param
    Box c = b;      // copy   (NOT assignment: c is being created)
    Box d(b);       // copy   (same thing, functional form)
    a = b;          // no constructor: assignment operator runs
}   // output ends: destroy5 destroy5 destroy5 destroy5  (d, c, b, a in reverse order)

class Buffer {
    int *data; int n;
public:
    Buffer(int size) : n(size), data(new int[size]) {}
    Buffer(const Buffer &o) : n(o.n), data(new int[o.n]) {   // DEEP copy
        for (int i = 0; i < n; i++) data[i] = o.data[i];
    }
    ~Buffer() { delete[] data; }
};
