#define N 8
static item_t buf[N];
static unsigned in = 0, out = 0;          /* next slot to write / to read  */
static sem_t empty, full;                 /* sem_init: empty = N, full = 0 */
static pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;

void put(item_t x)
{
    sem_wait(&empty);                     /* 1. reserve a free slot        */
    pthread_mutex_lock(&lock);            /* 2. then lock the index        */
    buf[in] = x;  in = (in + 1) % N;
    pthread_mutex_unlock(&lock);
    sem_post(&full);                      /* 3. announce one more item     */
}

/* Called from a timer ISR every T = 0.01 s */
float pid_step(float sp, float y) {
    static float integ = 0.0f, e_prev = 0.0f;
    float e = sp - y;
    integ += KI * T * e;
    float u = KP * e + integ + KD * (e - e_prev) / T;
    e_prev = e;
    if (u > U_MAX) { u = U_MAX; integ -= KI * T * e; }  /* anti-windup */
    if (u < U_MIN) { u = U_MIN; integ -= KI * T * e; }
    return u;
}

