void wait(semaphore *S) {          /* P */
    S->value--;
    if (S->value < 0) {
        add this process to S->list;
        block();
    }
}
void signal(semaphore *S) {        /* V */
    S->value++;
    if (S->value <= 0) {
        remove a process P from S->list;
        wakeup(P);
    }
}

